def add_plague(sc,aid="P",target="T",cast="LP",at=-2.9,ends=(4,10,16,22),die=8):
    sc.ev(at,"prior paid Leeching Plague commitment",lambda s:commit(s,aid,"leeching-plague",cast,{"target":target,"point":[*s.actors[target]["position"][:2],3],"actualHostilityForDrain":True,"lawfulTarget":True}))
