        dc=s.s["castLedger"][cast]["dc"];ok=save(s,target,"CON",die,dc,"Leeching Plague admission");finish(s,cast)
        if not ok:
            s.s["sources"][cast]={"id":cast,"spellId":"leeching-plague","owner":aid,"target":target,"rank":4,"state":"live","createdAt":s.s["time"],"due":list(ends),"settled":[],"nativeNoConcentration":True,"noRepeatSave":True,"hostileLivingNonconstructDonor":True}
    sc.ev(at+.1,"prior Plague admission",r)
def tick_plague(sc,cast="LP",dice=(3,3),woundDie=None):
    src=sc.s["sources"][cast];t=sc.s["time"];assert t in src["due"] and t not in src["settled"];src["settled"].append(t)
    target=src["target"];owner=src["owner"];a=sc.actors[target]
    if not a["alive"]:
        end_source(sc,cast,"recipient death");sc.obs["plague"]={"opportunity":t,"result":"no longer live"};return
    if a["bodyHold"]:
        sc.obs["plague"]={"opportunity":t,"result":"consumed without damage/heal/RNG under temporal body suspension","remaining":len(src["due"])-len(src["settled"])}
    else:
        actual=damage(sc,cast,target,list(dice),dtype="necrotic",woundDie=woundDie,provenance=owner)
        oa=sc.actors[owner];gain=0
        if oa["alive"] and oa["localPresent"] and not any(str(c).startswith("cannot-regain-HP") for c in oa["conditions"]):
            gain=min(oa["effectiveMaxHp"]-(1 if oa["critical"] else 0)-oa["hp"],actual//2);gain=max(0,gain);oa["hp"]+=gain
        sc.obs["plague"]={"opportunity":t,"rolled":list(dice),"actualDamageFunding":actual,"half":actual//2,"actualCasterHealing":gain,"currentAbsentTargetStillSameAttachedIdentity":not a["localPresent"]}
        if not a["alive"]:end_source(sc,cast,"target actual death")
    if len(src["settled"])==4:end_source(sc,cast,"four exact original installments spent")
def stasis(sc,cast,target,spell,end,kind,clockowner):
    owner=sc.s["castLedger"][cast]["caster"];key=f"{owner}/{target}/{sc.s['encounterId']}"
    if key in sc.s["hardGuard"]:
        sc.obs["stasisAdmission"]={"result":"blocked by spent whole-Action history","key":key};sc.actors[owner]["concentration"]=None if sc.actors[owner]["concentration"]==cast else sc.actors[owner]["concentration"];return
    if not sc.actors[target]["alive"]:sc.obs["stasisAdmission"]={"result":"recipient dead"};return
    sc.s["hardGuard"][key]={"cast":cast,"spentAt":sc.s["time"],"kind":"actual established equivalent whole-Action denial"}
    sc.s["sources"][cast]={"id":cast,"spellId":spell,"owner":owner,"target":target,"rank":6,"state":"live","createdAt":sc.s["time"],"deadline":end,"endKind":kind,"clockOwner":clockowner}
    sc.actors[target]["bodyHold"]=cast
    sc.obs["stasisAdmission"]={"key":key,"deadline":end,"actualEstablished":True,"noOrdinaryIncapacitatedAdded":True}
